const body=$json.body??$json;
const payload=body.payload??body;
const explicit=String(body.idempotencyKey??'').trim();
const canonical=JSON.stringify(payload,Object.keys(payload).sort());
let hash=0; for(let i=0;i<canonical.length;i++){hash=((hash<<5)-hash)+canonical.charCodeAt(i);hash|=0;}
const idempotencyKey=explicit||`demo-${Math.abs(hash)}`;
const valid=payload&&typeof payload==='object'&&!Array.isArray(payload)&&Object.keys(payload).length>0;
return [{json:{valid,idempotencyKey,payload,receivedAt:new Date().toISOString(),route:valid?'ACCEPT':'DLQ',reason:valid?null:'empty-or-invalid-payload'}}];
